package com.jinjiyunsun.pohjinglemute;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(PohJingleMuteProbeConfig.GROUP)
public interface PohJingleMuteProbeConfig extends Config
{
	String GROUP = "pohjinglemute-probe";

	enum TestMode
	{
		OFF("Off"),
		ZERO_THEN_TAIL("Mute, then tail volume"),
		ZERO_ONLY("Mute until end");

		private final String name;

		TestMode(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigSection(
		name = "Debug: timing test",
		description = "Mutes one jingle with setMusicVolume",
		position = 0
	)
	String timingSection = "timingSection";

	@ConfigItem(
		keyName = "testMode",
		name = "Mode",
		description = "Off: probe only logs.<br>"
			+ "Mute, then tail volume: mute volume<br>"
			+ "at jingle start, tail volume shortly<br>"
			+ "before its end, restore once it's gone.<br>"
			+ "Mute until end: mute volume until<br>"
			+ "it's gone.",
		section = timingSection,
		position = 0
	)
	default TestMode testMode()
	{
		return TestMode.OFF;
	}

	@ConfigItem(
		keyName = "jingleId",
		name = "Jingle ID",
		description = "MIDI archive ID of the jingle to mute.",
		section = timingSection,
		position = 1
	)
	default int jingleId()
	{
		return 112;
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "muteVolume",
		name = "Mute volume",
		description = "Volume while the jingle plays.<br>"
			+ "0 stops the jingle and the house track<br>"
			+ "never starts.",
		section = timingSection,
		position = 2
	)
	default int muteVolume()
	{
		return 1;
	}

	@Range(max = 60000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "jingleLength",
		name = "Jingle length",
		description = "Length from the cache.<br>"
			+ "Jingle 112 is 8000 ms.",
		section = timingSection,
		position = 3
	)
	default int jingleLength()
	{
		return 8000;
	}

	@Range(max = 60000)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "tailLead",
		name = "Tail lead",
		description = "How long before the jingle length<br>"
			+ "to switch to the tail volume.",
		section = timingSection,
		position = 4
	)
	default int tailLead()
	{
		return 500;
	}

	@Range(max = 100)
	@ConfigItem(
		keyName = "tailVolume",
		name = "Tail volume",
		description = "Volume for the end of the jingle,<br>"
			+ "so the house track starts above 0.",
		section = timingSection,
		position = 5
	)
	default int tailVolume()
	{
		return 1;
	}
}

package com.jinjiyunsun.pohjinglemute;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MidiRequest;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Logs active MIDI requests and music volume as they change.
 * With a test mode set, mutes one jingle using setMusicVolume only.
 */
@PluginDescriptor(
	name = "POH Jingle Mute Probe",
	developerPlugin = true
)
public class PohJingleMuteProbePlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(PohJingleMuteProbePlugin.class);

	// Restore anyway if the jingle is still listed this long after its length
	private static final long TIMEOUT_EXTRA_MS = 3000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private PohJingleMuteProbeConfig config;

	private String lastRequests = "";
	private long lastChangeNanos;
	private final Map<String, Long> firstSeenNanos = new HashMap<>();
	private int lastClientVolume = -1;
	private int lastOptionMusic = -1;

	private boolean jingleWasActive;
	private boolean muting;
	private boolean tailSet;
	private long muteStartNanos;
	private int savedVolume;

	@Provides
	PohJingleMuteProbeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PohJingleMuteProbeConfig.class);
	}

	@Override
	protected void startUp()
	{
		lastRequests = "";
		lastChangeNanos = System.nanoTime();
		firstSeenNanos.clear();
		lastClientVolume = -1;
		lastOptionMusic = -1;
		jingleWasActive = false;
		muting = false;
	}

	@Override
	protected void shutDown()
	{
		firstSeenNanos.clear();
		clientThread.invoke(() -> restore("probe stopped"));
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		log.debug("[probe] game state {}", event.getGameState());
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			restore("logged out");
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		long now = System.nanoTime();
		List<MidiRequest> active = client.getActiveMidiRequests();

		runTimingTest(active, now);
		checkVolume();

		List<String> current = new ArrayList<>();
		if (active != null)
		{
			for (MidiRequest request : active)
			{
				current.add((request.isJingle() ? "jingle " : "track ") + request.getArchiveId());
			}
		}

		String requests = String.join(", ", current);
		if (requests.equals(lastRequests))
		{
			return;
		}

		long sinceLast = (now - lastChangeNanos) / 1_000_000;
		StringBuilder line = new StringBuilder();
		line.append("MIDI [").append(requests).append("] +").append(sinceLast).append("ms");

		// Report how long each request that just disappeared was active
		for (Map.Entry<String, Long> entry : new ArrayList<>(firstSeenNanos.entrySet()))
		{
			if (!current.contains(entry.getKey()))
			{
				long lasted = (now - entry.getValue()) / 1_000_000;
				line.append(" | ended ").append(entry.getKey()).append(" after ").append(lasted).append("ms");
				firstSeenNanos.remove(entry.getKey());
			}
		}
		for (String request : current)
		{
			firstSeenNanos.putIfAbsent(request, now);
		}

		report(line.toString());
		lastRequests = requests;
		lastChangeNanos = now;
	}

	private void runTimingTest(List<MidiRequest> active, long now)
	{
		PohJingleMuteProbeConfig.TestMode mode = config.testMode();
		boolean jingleActive = isJingleActive(active, config.jingleId());

		if (!muting)
		{
			// Only start on the jingle appearing, so a timeout doesn't re-mute it
			if (mode != PohJingleMuteProbeConfig.TestMode.OFF && jingleActive && !jingleWasActive)
			{
				startMute(now);
			}
		}
		else
		{
			long elapsed = (now - muteStartNanos) / 1_000_000;
			if (mode == PohJingleMuteProbeConfig.TestMode.OFF)
			{
				restore("mode set to off");
			}
			else
			{
				if (mode == PohJingleMuteProbeConfig.TestMode.ZERO_THEN_TAIL && !tailSet
					&& elapsed >= config.jingleLength() - config.tailLead())
				{
					client.setMusicVolume(config.tailVolume());
					tailSet = true;
					report("test: volume " + config.tailVolume() + " at +" + elapsed + "ms, now " + describeActive());
				}

				boolean tailDone = mode == PohJingleMuteProbeConfig.TestMode.ZERO_ONLY || tailSet;
				if (!jingleActive && tailDone)
				{
					restore("jingle gone");
				}
				else if (elapsed >= config.jingleLength() + TIMEOUT_EXTRA_MS)
				{
					restore("timeout");
				}
			}
		}

		jingleWasActive = jingleActive;
	}

	private void startMute(long now)
	{
		int volume = client.getMusicVolume();
		if (volume <= 0)
		{
			report("test: jingle " + config.jingleId() + " started, music already at 0, skipped");
			return;
		}
		savedVolume = volume;
		muting = true;
		tailSet = false;
		muteStartNanos = now;
		client.setMusicVolume(config.muteVolume());
		report("test: jingle " + config.jingleId() + " started, volume " + config.muteVolume()
			+ " (saved " + volume + "), now " + describeActive());
	}

	private void restore(String reason)
	{
		if (!muting)
		{
			return;
		}
		long elapsed = (System.nanoTime() - muteStartNanos) / 1_000_000;
		client.setMusicVolume(savedVolume);
		muting = false;
		report("test: restored " + savedVolume + " at +" + elapsed + "ms (" + reason + "), now " + describeActive());
	}

	// Active MIDI list read right after a volume change
	private String describeActive()
	{
		List<String> names = new ArrayList<>();
		List<MidiRequest> active = client.getActiveMidiRequests();
		if (active != null)
		{
			for (MidiRequest request : active)
			{
				names.add((request.isJingle() ? "jingle " : "track ") + request.getArchiveId());
			}
		}
		return "[" + String.join(", ", names) + "]";
	}

	private static boolean isJingleActive(List<MidiRequest> active, int jingleId)
	{
		if (active == null)
		{
			return false;
		}
		for (MidiRequest request : active)
		{
			if (request.isJingle() && request.getArchiveId() == jingleId)
			{
				return true;
			}
		}
		return false;
	}

	private void checkVolume()
	{
		int clientVolume = client.getMusicVolume();
		int optionMusic = client.getVarpValue(VarPlayerID.OPTION_MUSIC);
		if (clientVolume != lastClientVolume || optionMusic != lastOptionMusic)
		{
			report("volume: client " + clientVolume + ", slider " + optionMusic);
			lastClientVolume = clientVolume;
			lastOptionMusic = optionMusic;
		}
	}

	private void report(String message)
	{
		log.debug("[probe] {}", message);
		// Other plugins' chat handlers can fail before the local player exists
		if (client.getLocalPlayer() == null)
		{
			return;
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[probe] " + message, null);
	}
}

package com.jinjiyunsun.pohjinglemute;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(PohJingleMuteConfig.GROUP)
public interface PohJingleMuteConfig extends Config
{
	String GROUP = "pohjinglemute";

	@ConfigItem(
		keyName = "mutedJingles",
		name = "Muted jingles",
		description = "Jingle IDs to mute, separated by commas,<br>"
			+ "e.g. 20, 112, 299<br>"
			+ "Starts with the house entrance jingles.<br>"
			+ "With Show track IDs on, a jingle's ID is<br>"
			+ "the orange number in chat.",
		position = 0
	)
	// The player-owned house entrance jingles, one per house style
	default String mutedJingles()
	{
		return "16, 18, 19, 20, 21, 22, 112, 279, 286, 307, 308";
	}

	@ConfigItem(
		keyName = "mutedTracks",
		name = "Muted tracks",
		description = "Music tracks to mute until the next track plays.<br>"
			+ "Track names or IDs, separated by commas,<br>"
			+ "e.g. 138, The Trade Parade<br>"
			+ "With Show track IDs on, the name is blue<br>"
			+ "and the ID is the orange number in chat.",
		position = 1
	)
	default String mutedTracks()
	{
		return "";
	}

	@ConfigItem(
		keyName = "showTrackIds",
		name = "Show track IDs",
		description = "Posts each track and jingle in chat as it starts,<br>"
			+ "to find the ones to mute.",
		position = 2
	)
	default boolean showTrackIds()
	{
		return false;
	}
}

package com.jinjiyunsun.pohjinglemute;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MidiRequest;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Music & Jingle Muter",
	description = "Mutes the music tracks and jingles you choose",
	tags = {"music", "track", "jingle", "mute", "sound", "annoyance", "annoying"}
)
public class PohJingleMutePlugin extends Plugin
{
	// The red the game uses in its own chat messages
	private static final Color PREFIX_COLOR = new Color(0xEF1020);
	// Readable on both the opaque and the transparent chatbox
	private static final Color ID_COLOR = new Color(0xFF9900);
	private static final Color NAME_COLOR = new Color(0x4FA8FF);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private PohJingleMuteConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	// Volume to put back on the next client tick, or -1 when nothing is muted
	private int restoreVolume = -1;
	// Listed requests already dealt with, as "jingle 299" or "track 496", so one that stays listed is never muted twice
	private Set<String> handledTargets = new HashSet<>();

	private Set<Integer> mutedJingles = new HashSet<>();
	private Set<Integer> mutedTracks = new HashSet<>();
	private Map<Integer, String> trackNames = new HashMap<>();
	// Requests seen last tick, as "jingle 299" or "track 496", for posting new ones
	private Set<String> lastRequests = new HashSet<>();
	// Set from the config thread; the lists are rebuilt on the client thread, where the music table can be read
	private volatile boolean listsChanged;

	@Provides
	PohJingleMuteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PohJingleMuteConfig.class);
	}

	@Override
	protected void startUp()
	{
		handledTargets = new HashSet<>();
		listsChanged = true;
		lastRequests = new HashSet<>();
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(this::restore);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(PohJingleMuteConfig.GROUP))
		{
			listsChanged = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			restore();
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		// The music table can only be read once the cache has loaded
		if (listsChanged && client.getGameState().getState() >= GameState.LOGIN_SCREEN.getState())
		{
			listsChanged = false;
			Map<String, Integer> idsByName = trackIdsByName();
			trackNames = new HashMap<>();
			idsByName.forEach((name, id) -> trackNames.put(id, name));
			mutedJingles = parseIds(config.mutedJingles(), null);
			mutedTracks = parseIds(config.mutedTracks(), idsByName);
		}

		List<MidiRequest> active = client.getActiveMidiRequests();
		// Before muting, so a request stopped this tick is still posted
		postNewRequests(active);

		Set<String> targets = muteTargets(active);
		// Forget targets that have stopped, so they're muted again if they come back
		handledTargets.retainAll(targets);

		// Restore a tick after muting: the request is gone by then and the next track not yet requested.
		// A target that appears on this tick is left unhandled and muted next tick
		if (restoreVolume >= 0)
		{
			restore();
		}
		else if (!handledTargets.containsAll(targets))
		{
			mute();
			handledTargets.addAll(targets);
		}
	}

	private void mute()
	{
		// getMusicVolume reads the saved setting, which setMusicVolume leaves alone
		int volume = client.getMusicVolume();
		if (volume <= 0)
		{
			return;
		}

		// Volume 0 stops the request outright, and a stopped track stays stopped until a new one is sent
		restoreVolume = volume;
		client.setMusicVolume(0);
	}

	// Listed requests now playing; a shared empty set when none, as is usual, to save making one each tick
	private Set<String> muteTargets(List<MidiRequest> active)
	{
		Set<String> targets = null;
		if (active != null)
		{
			for (MidiRequest request : active)
			{
				int id = request.getArchiveId();
				if (request.isJingle() ? mutedJingles.contains(id) : mutedTracks.contains(id))
				{
					if (targets == null)
					{
						targets = new HashSet<>();
					}
					targets.add(key(request));
				}
			}
		}
		return targets == null ? Collections.emptySet() : targets;
	}

	private static String key(MidiRequest request)
	{
		return (request.isJingle() ? "jingle " : "track ") + request.getArchiveId();
	}

	private void postNewRequests(List<MidiRequest> active)
	{
		// Forgetting what was seen means turning the option on posts what's already playing
		if (!config.showTrackIds())
		{
			lastRequests.clear();
			return;
		}

		Set<String> current = new HashSet<>();
		if (active != null)
		{
			for (MidiRequest request : active)
			{
				String key = key(request);
				current.add(key);
				// Only while logged in: the login screen has its own music, and chat isn't shown there
				if (!lastRequests.contains(key) && client.getGameState() == GameState.LOGGED_IN)
				{
					postRequest(request);
				}
			}
		}
		lastRequests = current;
	}

	private void postRequest(MidiRequest request)
	{
		int id = request.getArchiveId();
		String message;
		if (request.isJingle())
		{
			message = "Jingle " + ColorUtil.wrapWithColorTag(String.valueOf(id), ID_COLOR);
		}
		else
		{
			String name = trackNames.get(id);
			message = "Track " + ColorUtil.wrapWithColorTag(String.valueOf(id), ID_COLOR)
				+ (name == null ? "" : ": " + ColorUtil.wrapWithColorTag(name, NAME_COLOR));
		}
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			// Names the plugin, for players who forget the option is on
			.runeLiteFormattedMessage("[" + ColorUtil.wrapWithColorTag("Music & Jingle Muter", PREFIX_COLOR) + "] " + message)
			.build());
	}

	private void restore()
	{
		if (restoreVolume < 0)
		{
			return;
		}
		client.setMusicVolume(restoreVolume);
		restoreVolume = -1;
	}

	// Numbers are taken as IDs; anything else is looked up by name when a name map is given
	private static Set<Integer> parseIds(String list, Map<String, Integer> idsByName)
	{
		Set<Integer> ids = new HashSet<>();
		for (String entry : Text.fromCSV(list))
		{
			try
			{
				ids.add(Integer.parseInt(entry));
			}
			catch (NumberFormatException e)
			{
				Integer id = idsByName == null ? null : idsByName.get(entry);
				if (id != null)
				{
					ids.add(id);
				}
			}
		}
		return ids;
	}

	// Track names as shown in the music tab, from the game's music table; lookups ignore case
	private Map<String, Integer> trackIdsByName()
	{
		Map<String, Integer> ids = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (int row : client.getDBTableRows(DBTableID.Music.ID))
		{
			Object[] name = client.getDBTableField(row, DBTableID.Music.COL_DISPLAYNAME, 0);
			Object[] midi = client.getDBTableField(row, DBTableID.Music.COL_MIDI, 0);
			if (name.length > 0 && midi.length > 0 && name[0] instanceof String && midi[0] instanceof Integer)
			{
				ids.put((String) name[0], (Integer) midi[0]);
			}
		}
		return ids;
	}
}

package com.jinjiyunsun.pohjinglemute;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PohJingleMutePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PohJingleMutePlugin.class, PohJingleMuteProbePlugin.class);
		RuneLite.main(args);
	}
}
